(()=>{'use strict';
const KEY='cff-site-nav-stack-v1',MAX=24;let lastRoute='',suppress=false,observer=null;
const pathname=()=>location.pathname||'/';
const isIndexPath=(p=pathname())=>p==='/'||p==='/index.html'||p.endsWith('/index.html');
const activePage=()=>document.querySelector('.page.active')?.id||'home';
const currentRoute=()=>{if(isIndexPath()){const p=activePage();return p&&p!=='home'?`/index.html#${encodeURIComponent(p)}`:'/index.html'}return pathname()+location.search+location.hash};
const read=()=>{try{const v=JSON.parse(sessionStorage.getItem(KEY)||'[]');return Array.isArray(v)?v.filter(x=>typeof x==='string'&&x).slice(-MAX):[]}catch(_){return[]}};
const write=v=>{try{sessionStorage.setItem(KEY,JSON.stringify(v.slice(-MAX)))}catch(_){}};
const clear=()=>write([]);
function remember(route=currentRoute()){route=String(route||'');if(!route)return;const s=read();if(s[s.length-1]!==route)s.push(route);write(s)}
window.cffRememberRoute=remember;
function parseIndexTarget(target){try{const u=new URL(target,location.origin+'/');if(u.origin!==location.origin||!isIndexPath(u.pathname))return null;return decodeURIComponent((u.hash||'').replace(/^#/,'')||'home')}catch(_){return null}}
function rootTarget(target){try{return new URL(String(target||'/index.html'),location.origin+'/').href}catch(_){return location.origin+'/index.html'}}
function goBack(){const s=read();let target=s.pop()||'/index.html';write(s);const p=parseIndexTarget(target);if(isIndexPath()&&p&&typeof window.navigate==='function'){suppress=true;window.navigate(p);setTimeout(()=>{suppress=false;syncRoute()},0);return false}location.href=rootTarget(target);return false}
window.cffGoBack=goBack;
function makeButton(mobile=false){const b=document.createElement('button');b.type='button';b.className='cff-site-back-btn';b.setAttribute('aria-label','Voltar para a página anterior');b.innerHTML=mobile?'←':'← <span>VOLTAR</span>';b.addEventListener('click',goBack);return b}
function ensureButtons(){if(isIndexPath()){const dl=document.querySelector('.nav-desktop-left'),mb=document.querySelector('.nav-mobile-bar');if(dl&&!dl.querySelector('[data-cff-site-back]')){const b=makeButton(false);b.dataset.cffSiteBack='1';const menu=dl.querySelector('.nav-desktop-menu-btn');menu?.after(b)}if(mb&&!mb.querySelector('[data-cff-site-back]')){const b=makeButton(true);b.dataset.cffSiteBack='1';const menu=mb.querySelector('.nav-mob-menu-btn');menu?.after(b)}}else{const left=document.querySelector('.cff-public-left');if(left&&!left.querySelector('[data-cff-site-back]')){const b=makeButton(false);b.dataset.cffSiteBack='1';const menu=left.querySelector('.cff-public-menu-button');menu?.after(b)}else if(!left){const existing=document.querySelector('.news-back');if(existing){existing.dataset.cffSiteBack='1';existing.href='/index.html';existing.textContent='← Voltar';existing.addEventListener('click',e=>{e.preventDefault();goBack()})}else if(!document.querySelector('[data-cff-site-back]')){const b=makeButton(false);b.dataset.cffSiteBack='1';b.classList.add('cff-site-back-floating');document.body.appendChild(b)}}}updateButtons()}
function updateButtons(){const home=isIndexPath()&&activePage()==='home';document.querySelectorAll('[data-cff-site-back]').forEach(b=>{b.hidden=home})}
function syncRoute(){const cur=currentRoute();if(!lastRoute){lastRoute=cur;if(cur==='/index.html')clear();updateButtons();return}if(cur===lastRoute){updateButtons();return}if(!suppress)remember(lastRoute);lastRoute=cur;if(cur==='/index.html')clear();updateButtons()}
function watchSpa(){if(!isIndexPath())return;const root=document.getElementById('main-content')||document.body;if(!root)return;observer?.disconnect();observer=new MutationObserver(()=>syncRoute());observer.observe(root,{subtree:true,attributes:true,attributeFilter:['class']})}
function sameOriginDocumentLink(a){if(!a||a.dataset.cffSiteBack||a.target==='_blank'||a.hasAttribute('download'))return false;const raw=a.getAttribute('href');if(!raw||raw.startsWith('#')||/^(mailto:|tel:|javascript:)/i.test(raw))return false;try{const u=new URL(raw,document.baseURI||location.href);if(u.origin!==location.origin)return false;const same=u.pathname===location.pathname&&u.search===location.search;const html=/\.html?$/i.test(u.pathname),pretty=/^\/(?:equipe|jogador|noticias?|torneio)\//i.test(u.pathname),home=isIndexPath(u.pathname);return!same&&(html||pretty||home)}catch(_){return false}}
document.addEventListener('click',e=>{const a=e.target.closest?.('a[href]');if(sameOriginDocumentLink(a))remember();const el=e.target.closest?.('[onclick]');if(!a&&el){const code=el.getAttribute('onclick')||'';if(/open(?:CurrentSeason)?Player|openPlayerProfile|openTeamProfile|location\.href/i.test(code))remember()}},true);
function canonicalized(){lastRoute=currentRoute();updateButtons()}
function boot(){ensureButtons();lastRoute=currentRoute();if(lastRoute==='/index.html')clear();watchSpa();updateButtons();document.addEventListener('cff:modules-loaded',()=>{ensureButtons();syncRoute()});window.addEventListener('cff:pretty-route',canonicalized);window.addEventListener('popstate',syncRoute)}
document.readyState==='loading'?document.addEventListener('DOMContentLoaded',boot,{once:true}):boot();
})();
